926	arrow::Status SegmentHelper::FilterRecordBatch(
927	    const std::shared_ptr<arrow::RecordBatch> &batch,
928	    const IndexFilter::Ptr filter, uint32_t row_id_offset,
929	    std::shared_ptr<arrow::RecordBatch> *filterd,
930	    roaring::Roaring *delete_row_id_bitmap, uint64_t *min_doc_id,
931	    uint64_t *max_doc_id) {
932	  if (!filter) {
933	    *filterd = batch;
934	    for (int64_t i = 0; i < batch->num_rows(); ++i) {
935	      // column 0 is doc_id
936	      auto result = batch->column(0)->GetScalar(i);
937	      if (!result.ok()) {
938	        return result.status();
939	      }
940	      uint64_t doc_id =
941	          std::dynamic_pointer_cast<arrow::UInt64Scalar>(*result)->value;
942	      *min_doc_id = std::min(*min_doc_id, doc_id);
943	      *max_doc_id = std::max(*max_doc_id, doc_id);
944	    }
945	    return arrow::Status::OK();
946	  }
947	
948	  std::vector<uint64_t> selected_indices;
949	  for (int64_t i = 0; i < batch->num_rows(); ++i) {
950	    auto result = batch->column(0)->GetScalar(i);
951	    if (!result.ok()) {
952	      return result.status();
953	    }
954	    uint64_t doc_id =
955	        std::dynamic_pointer_cast<arrow::UInt64Scalar>(*result)->value;
956	    if (!filter->is_filtered(doc_id)) {
957	      selected_indices.push_back(i);
958	      *min_doc_id = std::min(*min_doc_id, doc_id);
959	      *max_doc_id = std::max(*max_doc_id, doc_id);
960	    } else {
961	      delete_row_id_bitmap->add(i + row_id_offset);
962	    }
963	  }
964	
965	  if (selected_indices.empty()) {
966	    return arrow::Status::OK();
967	  }
968	
969	  arrow::UInt64Builder builder;
970	  ARROW_RETURN_NOT_OK(builder.AppendValues(selected_indices));
971	  std::shared_ptr<arrow::Array> selection_array;
972	  ARROW_RETURN_NOT_OK(builder.Finish(&selection_array));
973	
974	  std::vector<std::shared_ptr<arrow::Array>> filtered_columns;
975	  for (int i = 0; i < batch->num_columns(); ++i) {
976	    arrow::Datum out;
977	    ARROW_ASSIGN_OR_RAISE(
978	        out, arrow::compute::Take(batch->column(i), selection_array));
979	    filtered_columns.push_back(out.make_array());
980	  }
981	
982	  auto filtered_batch = arrow::RecordBatch::Make(
983	      batch->schema(), static_cast<int64_t>(selected_indices.size()),
984	      filtered_columns);
985	
986	  *filterd = filtered_batch;
987	
988	  return arrow::Status::OK();
989	}
