177	Status SegmentHelper::ReduceScalar(
178	    const CollectionSchema::Ptr schema,
179	    const std::vector<Segment::Ptr> &input_segments,
180	    const std::string &output_segment_path,
181	    const std::vector<std::string> &columns, const IndexFilter::Ptr &filter,
182	    bool forward_use_parquet, std::function<BlockID()> &block_id_generator,
183	    roaring::Roaring *delete_row_id_bitmap,
184	    std::vector<BlockMeta> *output_block_metas, uint64_t *min_doc_id,
185	    uint64_t *max_doc_id, uint32_t *doc_count) {
186	  // forward
187	  auto forward_block_id = block_id_generator();
188	  auto forward_path = FileHelper::MakeForwardBlockPath(
189	      output_segment_path, forward_block_id, forward_use_parquet);
190	
191	  std::shared_ptr<ForwardWriter> forward_writer;
192	  if (forward_use_parquet) {
193	    forward_writer = ForwardWriter::CreateParquetWriter(forward_path);
194	  } else {
195	    forward_writer = ForwardWriter::CreateArrowIPCWriter(forward_path);
196	  }
197	
198	  // invert index
199	  auto all_fields = schema->fields();
200	  std::vector<FieldSchema> invert_fields;
201	  std::vector<std::string> invert_field_names;
202	  for (auto &field : all_fields) {
203	    if (!field->is_vector_field()) {
204	      if (field->index_params() &&
205	          field->index_params()->type() == IndexType::INVERT) {
206	        invert_fields.push_back(*field);
207	        invert_field_names.push_back(field->name());
208	      }
209	    }
210	  }
211	  InvertedIndexer::Ptr invert_indexer;
212	  BlockID invert_block_id{0};
213	  if (invert_fields.size() > 0) {
214	    invert_block_id = block_id_generator();
215	    auto invert_path =
216	        FileHelper::MakeInvertIndexPath(output_segment_path, invert_block_id);
217	    invert_indexer = InvertedIndexer::CreateAndOpen(schema->name(), invert_path,
218	                                                    true, invert_fields, false);
219	    if (invert_indexer == nullptr) {
220	      return Status::InternalError("Open invert indexer failed");
221	    }
222	  }
223	
224	  uint32_t row_id_offset{0U};
225	  *doc_count = 0;
226	
227	  std::vector<std::string> all_reduce_columns{GLOBAL_DOC_ID, USER_ID};
228	  for (auto &column : columns) {
229	    all_reduce_columns.push_back(column);
230	  }
231	
232	  for (auto &segment : input_segments) {
233	    auto reader = segment->scan(all_reduce_columns);
234	    if (reader == nullptr) {
235	      return Status::InternalError("scan segment failed");
236	    }
237	
238	    while (true) {
239	      auto batch = reader->Next();
240	      if (!batch.ok()) {
241	        return Status::InternalError("reader next failed: ",
242	                                     batch.status().message());
243	      }
244	
245	      auto batch_value = batch.ValueOrDie();
246	
247	      if (!batch_value) {
248	        break;
249	      }
250	
251	      if (batch_value->num_rows() == 0) continue;
252	
253	      std::shared_ptr<arrow::RecordBatch> filtered_batch;
254	      auto as =
255	          FilterRecordBatch(batch_value, filter, row_id_offset, &filtered_batch,
256	                            delete_row_id_bitmap, min_doc_id, max_doc_id);
257	      if (!as.ok()) {
258	        return Status::InternalError("filter record batch failed: ",
259	                                     as.message());
260	      }
261	
262	      row_id_offset += batch_value->num_rows();
263	
264	      if (!filtered_batch || filtered_batch->num_rows() == 0) {
265	        continue;
266	      }
267	
268	      // forward
269	      as = forward_writer->insert_batch(filtered_batch);
270	      if (!as.ok()) {
271	        return Status::InternalError("writer insert failed: ", as.message());
272	      }
273	
274	      // invert index
275	      if (invert_indexer) {
276	        auto s = ReduceScalarIndex(invert_indexer, filtered_batch, *doc_count);
277	        CHECK_RETURN_STATUS(s);
278	      }
279	
280	      *doc_count += filtered_batch->num_rows();
281	    }
282	  }
283	
284	  if (*doc_count == 0) {
285	    // no docs
286	    return Status::OK();
287	  }
288	
289	  // flush forward
290	  auto as = forward_writer->finalize();
291	  if (!as.ok()) {
292	    return Status::InternalError("writer finalize failed: ", as.message());
293	  }
294	
295	  BlockMeta forward_meta;
296	  forward_meta.set_id(forward_block_id);
297	  forward_meta.set_type(BlockType::SCALAR);
298	  forward_meta.set_min_doc_id(*min_doc_id);
299	  forward_meta.set_max_doc_id(*max_doc_id);
300	  forward_meta.set_doc_count(*doc_count);
301	  forward_meta.set_columns(all_reduce_columns);
302	
303	  output_block_metas->push_back(forward_meta);
304	
305	  if (invert_indexer) {
306	    auto s = invert_indexer->flush();
307	    CHECK_RETURN_STATUS(s);
308	
309	    s = invert_indexer->seal();
310	    CHECK_RETURN_STATUS(s);
311	
312	    BlockMeta meta;
313	    meta.set_id(invert_block_id);
314	    meta.set_type(BlockType::SCALAR_INDEX);
315	
316	    output_block_metas->push_back(meta);
317	  }
318	
319	  LOG_INFO("Compacted scalar and scalar index");
320	
321	  return Status::OK();
322	}
323	
324	Status SegmentHelper::ReduceScalarIndex(
325	    InvertedIndexer::Ptr invert_indexer,
326	    const std::shared_ptr<arrow::RecordBatch> &batch, uint32_t doc_id_offset) {
327	  auto a_schema = batch->schema();
328	  int num_columns = batch->num_columns();
329	
330	  for (int i = 0; i < num_columns; ++i) {
331	    auto field = a_schema->field(i);
332	    auto column_name = field->name();
333	
334	    auto indexer = (*invert_indexer)[column_name];
335	    if (!indexer) {
336	      continue;
337	    }
338	
339	    auto array = batch->column(i);
340	    auto type_id = field->type()->id();
341	
342	    Status s;
343	
344	    switch (type_id) {
345	      case arrow::Type::BOOL: {
346	        auto typed_array = std::static_pointer_cast<arrow::BooleanArray>(array);
347	        for (int64_t j = 0; j < typed_array->length(); ++j) {
348	          if (!typed_array->IsNull(j)) {
349	            bool value = typed_array->Value(j);
350	            s = indexer->insert(j + doc_id_offset, value);
351	            CHECK_RETURN_STATUS(s);
352	          } else {
353	            s = indexer->insert_null(j + doc_id_offset);
354	            CHECK_RETURN_STATUS(s);
355	          }
356	        }
357	        break;
358	      }
359	      case arrow::Type::INT32: {
360	        auto typed_array = std::static_pointer_cast<arrow::Int32Array>(array);
361	        for (int64_t j = 0; j < typed_array->length(); ++j) {
362	          if (!typed_array->IsNull(j)) {
363	            int32_t value = typed_array->Value(j);
364	            std::string value_str(reinterpret_cast<const char *>(&value),
365	                                  sizeof(value));
366	            s = indexer->insert(j + doc_id_offset, value_str);
367	            CHECK_RETURN_STATUS(s);
368	          } else {
369	            s = indexer->insert_null(j + doc_id_offset);
370	            CHECK_RETURN_STATUS(s);
371	          }
372	        }
373	        break;
374	      }
375	      case arrow::Type::INT64: {
376	        auto typed_array = std::static_pointer_cast<arrow::Int64Array>(array);
377	        for (int64_t j = 0; j < typed_array->length(); ++j) {
378	          if (!typed_array->IsNull(j)) {
379	            int64_t value = typed_array->Value(j);
380	            std::string value_str(reinterpret_cast<const char *>(&value),
381	                                  sizeof(value));
382	            s = indexer->insert(j + doc_id_offset, value_str);
383	            CHECK_RETURN_STATUS(s);
384	          } else {
385	            s = indexer->insert_null(j + doc_id_offset);
386	            CHECK_RETURN_STATUS(s);
387	          }
388	        }
389	        break;
390	      }
391	      case arrow::Type::UINT32: {
392	        auto typed_array = std::static_pointer_cast<arrow::UInt32Array>(array);
393	        for (int64_t j = 0; j < typed_array->length(); ++j) {
394	          if (!typed_array->IsNull(j)) {
395	            uint32_t value = typed_array->Value(j);
396	            std::string value_str(reinterpret_cast<const char *>(&value),
397	                                  sizeof(value));
398	            s = indexer->insert(j + doc_id_offset, value_str);
399	            CHECK_RETURN_STATUS(s);
400	          } else {
401	            s = indexer->insert_null(j + doc_id_offset);
402	            CHECK_RETURN_STATUS(s);
403	          }
404	        }
405	        break;
406	      }
407	      case arrow::Type::UINT64: {
408	        auto typed_array = std::static_pointer_cast<arrow::UInt64Array>(array);
409	        for (int64_t j = 0; j < typed_array->length(); ++j) {
410	          if (!typed_array->IsNull(j)) {
411	            uint64_t value = typed_array->Value(j);
412	            std::string value_str(reinterpret_cast<const char *>(&value),
413	                                  sizeof(value));
414	            s = indexer->insert(j + doc_id_offset, value_str);
415	            CHECK_RETURN_STATUS(s);
416	          } else {
417	            s = indexer->insert_null(j + doc_id_offset);
418	            CHECK_RETURN_STATUS(s);
419	          }
420	        }
421	        break;
422	      }
423	      case arrow::Type::FLOAT: {
424	        auto typed_array = std::static_pointer_cast<arrow::FloatArray>(array);
425	        for (int64_t j = 0; j < typed_array->length(); ++j) {
426	          if (!typed_array->IsNull(j)) {
427	            float value = typed_array->Value(j);
428	            std::string value_str(reinterpret_cast<const char *>(&value),
429	                                  sizeof(value));
430	            s = indexer->insert(j + doc_id_offset, value_str);
431	            CHECK_RETURN_STATUS(s);
432	          } else {
433	            s = indexer->insert_null(j + doc_id_offset);
434	            CHECK_RETURN_STATUS(s);
435	          }
436	        }
437	        break;
438	      }
439	      case arrow::Type::DOUBLE: {
440	        auto typed_array = std::static_pointer_cast<arrow::DoubleArray>(array);
441	        for (int64_t j = 0; j < typed_array->length(); ++j) {
442	          if (!typed_array->IsNull(j)) {
443	            double value = typed_array->Value(j);
444	            std::string value_str(reinterpret_cast<const char *>(&value),
445	                                  sizeof(value));
446	            s = indexer->insert(j + doc_id_offset, value_str);
447	            CHECK_RETURN_STATUS(s);
448	          } else {
449	            s = indexer->insert_null(j + doc_id_offset);
450	            CHECK_RETURN_STATUS(s);
451	          }
452	        }
453	        break;
454	      }
455	      case arrow::Type::STRING: {
456	        auto typed_array = std::static_pointer_cast<arrow::StringArray>(array);
457	        for (int64_t j = 0; j < typed_array->length(); ++j) {
458	          if (!typed_array->IsNull(j)) {
459	            std::string value_str = typed_array->GetString(j);
460	            s = indexer->insert(j + doc_id_offset, value_str);
461	            CHECK_RETURN_STATUS(s);
462	          } else {
463	            s = indexer->insert_null(j + doc_id_offset);
464	            CHECK_RETURN_STATUS(s);
465	          }
466	        }
467	        break;
468	      }
469	      case arrow::Type::LIST: {
470	        auto list_array = std::static_pointer_cast<arrow::ListArray>(array);
471	        auto value_array = list_array->values();
472	        auto value_type_id = value_array->type()->id();
473	
474	        auto offset_array = list_array->offsets();
475	        auto typed_offsets =
476	            std::static_pointer_cast<arrow::Int32Array>(offset_array);
477	
478	        for (int64_t j = 0; j < list_array->length(); ++j) {
479	          if (list_array->IsNull(j)) {
480	            s = (*invert_indexer)[column_name]->insert_null(j + doc_id_offset);
481	            CHECK_RETURN_STATUS(s);
482	            continue;
483	          }
484	
485	          int32_t start_offset = typed_offsets->Value(j);
486	          int32_t end_offset = typed_offsets->Value(j + 1);
487	
488	          switch (value_type_id) {
489	            case arrow::Type::BOOL: {
490	              std::vector<bool> values;
491	              auto typed =
492	                  std::static_pointer_cast<arrow::BooleanArray>(value_array);
493	              for (int32_t k = start_offset; k < end_offset; ++k) {
