760	// Only the first indexer's file is reused as the merge base; the remaining
761	// indexers are merged in via Merge(). Reuse is restricted to streaming
762	// indexes (HNSW, FLAT). Builder-rebuild indexes (IVF, VAMANA) and HNSW_RABITQ
763	// fall back to the full-rebuild merge.
764	bool CanReuseFirstIndexer(const std::vector<VectorColumnIndexer::Ptr> &indexers,
765	                          const FieldSchema &output_field,
766	                          const IndexFilter::Ptr &filter) {
767	  if (filter != nullptr || indexers.empty()) {
768	    return false;
769	  }
770	  if (output_field.index_type() != IndexType::HNSW &&
771	      output_field.index_type() != IndexType::FLAT) {
772	    return false;
773	  }
774	  const auto &first_field = indexers.front()->field_schema();
775	  if (first_field.index_type() != output_field.index_type()) {
776	    return false;
777	  }
778	
779	  // When creating a quantized column, the fp32 indexers will be merged into a
780	  // quantized vector indexer.
781	  auto quantize_type_of = [](const FieldSchema &f) {
782	    auto params =
783	        std::dynamic_pointer_cast<VectorIndexParams>(f.index_params());
784	    return params ? params->quantize_type() : QuantizeType::UNDEFINED;
785	  };
786	  return quantize_type_of(first_field) == quantize_type_of(output_field);
787	}
788	
789	}  // namespace
