791	Status SegmentHelper::MergeWithOptionalReuse(
792	    const std::string &output_index_path, const FieldSchema &index_field,
793	    std::vector<VectorColumnIndexer::Ptr> source_indexers,
794	    const IndexFilter::Ptr &filter, int concurrency,
795	    VectorColumnIndexer::Ptr *merged_indexer) {
796	  vector_column_params::MergeOptions merge_options;
797	  if (concurrency == 0) {
798	    merge_options.pool = GlobalResource::Instance().optimize_thread_pool();
799	    merge_options.write_concurrency =
800	        GlobalConfig::Instance().optimize_thread_count();
801	  } else {
802	    merge_options.write_concurrency = concurrency;
803	  }
804	  auto vector_indexer =
805	      std::make_shared<VectorColumnIndexer>(output_index_path, index_field);
806	  bool reused_base_index = false;
807	  Status s;
808	
809	  if (CanReuseFirstIndexer(source_indexers, index_field, filter)) {
810	    const auto &first_indexer = source_indexers.front();
811	    LOG_INFO(
812	        "Reusing first indexer as merge base. "
813	        "field[%s] src[%s] dst[%s] tail_indexers[%zu]",
814	        index_field.name().c_str(), first_indexer->index_file_path().c_str(),
815	        output_index_path.c_str(), source_indexers.size() - 1);
816	    if (FileHelper::CopyFile(first_indexer->index_file_path(),
817	                             output_index_path)) {
818	      // Open the copied file in-place (create_new=false).
819	      s = vector_indexer->Open(vector_column_params::ReadOptions{true, false});
820	      CHECK_RETURN_STATUS(s);
821	
822	      source_indexers.erase(source_indexers.begin());
823	      s = vector_indexer->Merge(source_indexers, filter, merge_options);
824	      CHECK_RETURN_STATUS(s);
825	      reused_base_index = true;
826	    } else {
827	      LOG_WARN("Failed to copy %s to %s; falling back to full rebuild",
828	               first_indexer->index_file_path().c_str(),
829	               output_index_path.c_str());
830	    }
831	  }
832	
833	  if (!reused_base_index) {
834	    s = vector_indexer->Open(vector_column_params::ReadOptions{true, true});
835	    CHECK_RETURN_STATUS(s);
836	
837	    s = vector_indexer->Merge(source_indexers, filter, merge_options);
838	    CHECK_RETURN_STATUS(s);
839	  }
840	
841	  s = vector_indexer->Flush();
842	  CHECK_RETURN_STATUS(s);
843	  if (merged_indexer != nullptr) {
844	    *merged_indexer = vector_indexer;
845	  } else {
846	    s = vector_indexer->Close();
847	    CHECK_RETURN_STATUS(s);
848	  }
849	  return Status::OK();
850	}
